import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

// Use the published CLI and runner directly: cmd.exe does not understand the
// POSIX single-quoted paths generated by the CLI's default test command.
const result = spawnSync(process.execPath, [
  fileURLToPath(new URL('../node_modules/piezas/src/index.js', import.meta.url)),
  'test', ...process.argv.slice(2),
], {
  cwd: fileURLToPath(new URL('../', import.meta.url)),
  env: {
    ...process.env,
    PIEZAS_TEST_CMD: 'node node_modules/@playwright/test/cli.js test --reporter=json --retries=1',
  },
  stdio: 'inherit',
});
if (result.error) console.error(result.error.message);
process.exit(result.status ?? 1);
